<style>
@font-face{font-family:Postal;src:url(data:font/ttf;base64,) format('truetype');font-weight:600;font-display:swap}
:root{--blue:#123fa4;--deep:#122d66;--sky:#d7eff9;--white:#fff;--orange:#aa390f;--yellow:#ffdd63;--pale:#eef7fc;--muted:#3f5c7b;--green:#176043;--rule:#a5c4df}
*{box-sizing:border-box}
body{margin:0;background:var(--sky);color:var(--deep);font:17px/1.55 system-ui,sans-serif;scrollbar-color:var(--blue) var(--sky)}
