.clock{font-size:clamp(3.5rem,8vw,5rem);font-variant-numeric:tabular-nums;color:var(--blue);line-height:1.25;display:block;margin:5px 0}
.clock small{font:700 1rem system-ui,sans-serif;margin-left:7px}
