.scrub button{padding:0;font-size:1.35rem}
input[type=range]{width:100%;min-width:0;height:48px;margin:0}
.range-ends{display:flex;justify-content:space-between;font-size:.8rem;color:var(--muted);margin:0 60px}
.departure{margin:18px 0;border-block:1px solid var(--rule);padding:13px 0}
.departure span{display:block;font-size:.88rem;color:var(--muted)}
.departure strong{font-size:1.05rem;font-variant-numeric:tabular-nums}
