.feedback{margin-top:18px;padding:16px;background:var(--white);border-radius:12px}
.feedback p{margin:0}
.feedback.good{background:var(--blue);color:var(--white)}
.feedback.bad{color:var(--orange)}
.feedback button{margin-top:15px}
#arrival{font-weight:750;font-variant-numeric:tabular-nums}
#hintText{margin:16px 0 0;color:var(--muted);font-size:.95rem}
#cancel{display:inline-block;border:2px solid currentColor;border-radius:50%;padding:16px 10px;font-family:Postal,sans-serif;line-height:1;text-align:center;transform:rotate(-10deg);color:var(--orange);margin-top:15px}
.stamp-in{animation:stamp .45s cubic-bezier(.16,1,.3,1)}
@keyframes stamp{from{transform:scale(1.12) rotate(-5deg);filter:saturate(1.8)}to{transform:scale(1) rotate(-10deg);filter:saturate(1)}}
.lesson{margin-top:42px;border-top:1px solid var(--blue);padding-top:22px;display:grid;grid-template-columns:1fr 1fr;gap:36px}
.lesson h2{font-size:1.65rem}.lesson p{margin:0 0 12px;max-width:70ch}
details{margin-top:14px}summary{cursor:pointer;min-height:44px;font-weight:700}
details p{font-size:.94rem;color:var(--muted)}
.finish{margin-top:28px;padding:30px;background:var(--blue);color:var(--white);border-radius:12px}
.finish h2{font-size:2.6rem}.finish p{max-width:65ch}
.finish button{background:var(--yellow);color:var(--deep)}
#log{padding:0;list-style:none}#log li{border-top:1px solid #6d90dc;padding:12px 0;font-size:.95rem}
