footer p{margin:5px 0}
@media(max-width:700px){
.shell{padding:12px 18px 32px}.masthead{display:block;padding-top:15px}.masthead p{margin-top:8px;font-size:1rem;max-width:45ch}
.cover img{height:185px;object-position:50% 54%}.cover figcaption{font-size:.76rem;padding:7px 12px}.cover figcaption span:last-child{display:none}
.work{grid-template-columns:1fr;gap:22px;margin-top:21px}.letter{padding:21px}.postmarks{padding:17px 0}.postmarks p{max-width:12ch;font-size:.82rem}#stamps{gap:6px}#stamps li{width:28px;height:28px;font-size:.82rem}
.lesson{grid-template-columns:1fr;gap:20px;margin-top:30px}.clock{font-size:4rem}.target{font-size:1.65rem}.letter p{margin:9px 0}.route{margin:14px 0}
}
@media(max-width:360px){.shell{padding-inline:14px}.postmarks{gap:10px}#stamps{gap:5px}#stamps li{width:25px;height:25px}.actions button{flex:1;padding-inline:10px}.cover img{height:165px}.date-row{gap:8px}.date-row label{font-size:.9rem}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}
